import { Effect, FileSystem } from "effect"
import type { PlatformError } from "effect/PlatformError"
import { type ResolvedConfig, identityPaths } from "./config.ts"
import { AuthError, MissingTool } from "./errors.ts"
import { lastProcessLine, runCaptured, runExitCode, type ProcessReq } from "./process.ts"
import {
  CURL_INSTALL,
  caUnreachableHint,
  caUnreachableMessage,
} from "./recover.ts"
import { resolveStep } from "./tools.ts"

export { caUnreachableHint } from "./recover.ts"

export interface AuthHooks {
  readonly onSigning?: () => void
}

type AuthBase = {
  /** ssh args for the control plane (`pu@host`). */
  readonly sshArgs: ReadonlyArray<string>
  /** ssh args for an instance hop (no known-hosts file). */
  readonly instanceSshArgs: ReadonlyArray<string>
}

export type Auth =
  | (AuthBase & {
      readonly useSshCa: false
    })
  | (AuthBase & {
      readonly useSshCa: true
      readonly identityFile: string
      readonly certificateFile: string
    })

const MAC_OPT =
  "MACs=hmac-sha2-256-etm@openssh.com,hmac-sha2-512-etm@openssh.com,umac-128-etm@openssh.com"

const macArgs = ["-o", MAC_OPT] as const

export const stepEnv = (
  config: ResolvedConfig,
): Record<string, string> => ({
  STEP_FINGERPRINT: config.stepFingerprint,
  STEP_CA_URL: config.stepCaUrl,
})

const requireStep = Effect.gen(function* () {
  const step = resolveStep()
  const code = yield* runExitCode(step, ["version"], {
    stdout: "ignore",
    stderr: "ignore",
  }).pipe(Effect.orElseSucceed(() => 127))
  if (code === 127) {
    return yield* new MissingTool({
      tool: "step",
      hint: `Install it with the curl installer (also drops official step):\n\n  ${CURL_INSTALL}`,
    })
  }
  if (code !== 0) {
    return yield* new AuthError({
      message: `step at ${step} exited ${code} (it is installed; this is not a missing PATH).`,
      hint: `Reinstall:\n\n  ${CURL_INSTALL}\n\nOr set XYNE_STEP to a working binary.`,
    })
  }
})

export const ensureAuth = (
  config: ResolvedConfig,
  hooks: AuthHooks = {},
): Effect.Effect<
  Auth,
  AuthError | MissingTool | PlatformError,
  ProcessReq | FileSystem.FileSystem
> =>
  Effect.gen(function* () {
    const fs = yield* FileSystem.FileSystem
    yield* fs.makeDirectory(config.stateDir, { recursive: true })

    if (!config.useSshCa) {
      return {
        useSshCa: false,
        sshArgs: [...macArgs, "-o", "StrictHostKeyChecking=no"],
        instanceSshArgs: [...macArgs],
      }
    }

    yield* requireStep

    const step = resolveStep()
    const paths = identityPaths(config.stateDir)
    const env = stepEnv(config)

    if (!(yield* fs.exists(paths.key))) {
      const generated = yield* runCaptured("ssh-keygen", [
        "-q",
        "-t",
        "ed25519",
        "-N",
        "",
        "-f",
        paths.key,
      ])
      if (generated.exitCode !== 0) {
        const detail = lastProcessLine(generated)
        return yield* new AuthError({
          message: detail || `ssh-keygen failed writing ${paths.key}.`,
          hint: "OpenSSH ssh-keygen must be on PATH. Stock macOS and Linux ship it as ssh-keygen.",
        })
      }
    }

    yield* Effect.logDebug(`CA ${config.stepCaUrl} host=${config.host}`)
    const healthy = yield* runExitCode(step, ["ca", "health"], {
      env,
      stdout: "ignore",
      stderr: "ignore",
    }).pipe(Effect.orElseSucceed(() => 1))
    yield* Effect.logDebug(`step ca health exit=${healthy}`)
    if (healthy !== 0) {
      yield* Effect.logDebug("step ca bootstrap")
      const bootstrapped = yield* runCaptured(step, ["ca", "bootstrap", "--force"], { env })
      if (bootstrapped.exitCode !== 0) {
        const detail = lastProcessLine(bootstrapped)
        const said = detail !== "" ? `step said: ${detail}` : undefined
        return yield* new AuthError({
          message: caUnreachableMessage(config.host, config.stepCaUrl),
          hint: [said, caUnreachableHint(config.host, detail)].filter(Boolean).join("\n\n"),
        })
      }
    }

    const certOk = yield* fs.exists(paths.cert)
    const provisioner = certOk
      ? (yield* fs.exists(paths.provisionerFile))
        ? (yield* fs.readFileString(paths.provisionerFile)).trim()
        : ""
      : ""
    const needsRenewal =
      !certOk ||
      provisioner !== config.provisioner ||
      (yield* runExitCode(step, [
        "ssh",
        "needs-renewal",
        paths.cert,
        "--expires-in",
        "168h",
      ], {
        env,
        stdout: "ignore",
        stderr: "ignore",
      }).pipe(Effect.orElseSucceed(() => 1))) === 0

    if (needsRenewal) {
      yield* Effect.logDebug("signing SSH certificate")
      hooks.onSigning?.()
      const signed = yield* runExitCode(step, [
        "ssh",
        "certificate",
        "--force",
        "--no-agent",
        "--no-password",
        "--insecure",
        "--provisioner",
        config.provisioner,
        "--console",
        "me",
        paths.key,
      ], { env, stdout: "inherit", stderr: "inherit" })
      if (signed !== 0) {
        return yield* new AuthError({
          message: `Could not sign an SSH certificate (step exited ${signed}).`,
          hint: "step prints a URL and a code. Open the URL, enter the code, sign in with your Juspay Google account, then rerun the same command.",
        })
      }
      yield* fs.writeFileString(paths.provisionerFile, `${config.provisioner}\n`)
    }

    const identityArgs = [
      "-i",
      paths.key,
      "-o",
      `CertificateFile=${paths.cert}`,
      "-o",
      "IdentitiesOnly=yes",
    ] as const

    return {
      useSshCa: true,
      identityFile: paths.key,
      certificateFile: paths.cert,
      sshArgs: [
        ...macArgs,
        ...identityArgs,
        "-o",
        `UserKnownHostsFile=${paths.knownHosts}`,
        "-o",
        "StrictHostKeyChecking=accept-new",
      ],
      instanceSshArgs: [...macArgs, ...identityArgs],
    }
  })

import { describe, expect, test } from "bun:test"
import { resolveStep } from "./tools.ts"

describe("resolveStep", () => {
  test("XYNE_STEP wins", () => {
    const prev = process.env["XYNE_STEP"]
    process.env["XYNE_STEP"] = "/opt/step"
    try {
      expect(resolveStep()).toBe("/opt/step")
    } finally {
      if (prev === undefined) delete process.env["XYNE_STEP"]
      else process.env["XYNE_STEP"] = prev
    }
  })
})

import { afterEach, describe, expect, test } from "bun:test"
import { commitHash, commitLabel, versionString } from "./build-info.ts"
import pkg from "../package.json" with { type: "json" }

describe("commitHash", () => {
  const prev = process.env["XYNE_COMMIT"]

  afterEach(() => {
    if (prev === undefined) delete process.env["XYNE_COMMIT"]
    else process.env["XYNE_COMMIT"] = prev
  })

  test("reads XYNE_COMMIT when the baked value is empty", () => {
    process.env["XYNE_COMMIT"] = "41803636ecbde0b97f7b9b1735f5c67452dd06aa"
    expect(commitHash()).toBe("41803636ecbde0b97f7b9b1735f5c67452dd06aa")
    expect(versionString()).toBe(`${pkg.version} (41803636ecbde0b97f7b9b1735f5c67452dd06aa)`)
  })

  test("treats placeholders as unknown", () => {
    process.env["XYNE_COMMIT"] = "__XYNE_COMMIT__"
    expect(commitHash()).toBeUndefined()
    expect(commitLabel()).toBe("unknown")
    expect(versionString()).toBe(pkg.version)
  })
})

import { describe, expect, test } from "bun:test"
import { envFlag, resolveConfig } from "./config.ts"

describe("envFlag", () => {
  test("treats false and 0 as off", () => {
    expect(envFlag("false", true)).toBe(false)
    expect(envFlag("0", true)).toBe(false)
    expect(envFlag("true", false)).toBe(true)
    expect(envFlag(undefined, true)).toBe(true)
  })
})

describe("resolveConfig", () => {
  test("options win over env", () => {
    const config = resolveConfig({
      host: "other",
      admin: "root",
      useSshCa: false,
      stateDir: "/tmp/pu",
    })
    expect(config.host).toBe("other")
    expect(config.admin).toBe("root")
    expect(config.useSshCa).toBe(false)
    expect(config.stateDir).toBe("/tmp/pu")
    expect(config.stepCaUrl).toBe("https://other:8443")
  })
})

import { describe, expect, test } from "bun:test"
import { parseConnectArgs } from "./connect-args.ts"
import { UsageError } from "xyne-boxes"

describe("parseConnectArgs", () => {
  test("requires a name", () => {
    const parsed = parseConnectArgs([], "xyne-boxes")
    expect(parsed).toBeInstanceOf(UsageError)
  })

  test("rejects a path-like name", () => {
    const parsed = parseConnectArgs(["../etc"], "xyne-boxes")
    expect(parsed).toBeInstanceOf(UsageError)
  })

  test("bare connect is just the name", () => {
    expect(parseConnectArgs(["mybox"], "xyne-boxes")).toEqual({
      name: "mybox",
      sshArgs: [],
      remoteCmd: [],
    })
  })

  test("unflagged rest is a remote command", () => {
    expect(parseConnectArgs(["mybox", "uname", "-a"], "xyne-boxes")).toEqual({
      name: "mybox",
      sshArgs: [],
      remoteCmd: ["uname", "-a"],
    })
  })

  test("ssh options then -- remote", () => {
    expect(
      parseConnectArgs(["mybox", "-o", "ForwardAgent=yes", "--", "echo", "hi"], "xyne-boxes"),
    ).toEqual({
      name: "mybox",
      sshArgs: ["-o", "ForwardAgent=yes"],
      remoteCmd: ["echo", "hi"],
    })
  })
})

import { describe, expect, test } from "bun:test"
import { invalidBoxName } from "./names.ts"

describe("invalidBoxName", () => {
  test("accepts the names we actually use", () => {
    expect(invalidBoxName("mybox")).toBeUndefined()
    expect(invalidBoxName("app-pr-42")).toBeUndefined()
    expect(invalidBoxName("a.b_c-1")).toBeUndefined()
  })

  test("rejects empty, spaces, and path separators", () => {
    expect(invalidBoxName("")).toContain("Box name is empty")
    expect(invalidBoxName("../etc")).toContain("\"../etc\" is not a valid box name")
    expect(invalidBoxName("a b")).toContain("\"a b\" is not a valid box name")
    expect(invalidBoxName("a b")).toContain("app-pr-42")
  })
})

import { describe, expect, test } from "bun:test"
import { namesFromList, parseList } from "./list.ts"

describe("parseList", () => {
  test("skips a header and splits name + location", () => {
    expect(parseList("NAME LOCATION\napp-pr-42 host-a\n")).toEqual([
      { name: "app-pr-42", location: "host-a", extra: [] },
    ])
  })

  test("parses a pipe table from the server", () => {
    expect(
      parseList(`NAME | LOCATION |
headscale-in1 | dev-x86-64-linux-03 |
kolu-bot | dev-x86-64-linux-08 |
`),
    ).toEqual([
      { name: "headscale-in1", location: "dev-x86-64-linux-03", extra: [] },
      { name: "kolu-bot", location: "dev-x86-64-linux-08", extra: [] },
    ])
  })

  test("skips ascii table rules", () => {
    expect(
      parseList(`+------+----------+
| NAME | LOCATION |
+------+----------+
| box  | host-a   |
+------+----------+
`),
    ).toEqual([{ name: "box", location: "host-a", extra: [] }])
  })

  test("treats an empty listing as no rows", () => {
    expect(parseList("\n")).toEqual([])
  })

  test("keeps a box literally named name", () => {
    expect(parseList("NAME LOCATION\nname host-a\n")).toEqual([
      { name: "name", location: "host-a", extra: [] },
    ])
  })

  test("keeps leftover columns", () => {
    expect(parseList("box host extra bits")).toEqual([
      { name: "box", location: "host", extra: ["extra", "bits"] },
    ])
  })
})

describe("namesFromList", () => {
  test("returns valid unique names in order", () => {
    expect(
      namesFromList(`NAME | LOCATION |
headscale-in1 | dev-x86-64-linux-03 |
kolu-bot | dev-x86-64-linux-08 |
headscale-in1 | dev-x86-64-linux-03 |
`),
    ).toEqual(["headscale-in1", "kolu-bot"])
  })

  test("empty listing means prune everything", () => {
    expect(namesFromList("\n")).toEqual([])
    expect(namesFromList("")).toEqual([])
  })

  test("drops invalid names and refuses to parse leftover junk", () => {
    expect(namesFromList("foo/bar host\n!!! nope\n")).toBeUndefined()
  })

  test("keeps a mix that still has at least one valid name", () => {
    expect(namesFromList("ok-box host\nfoo/bar host\n")).toEqual(["ok-box"])
  })
})

import { describe, expect, test } from "bun:test"
import { isVerbose, takeVerbose } from "./verbose.ts"

describe("takeVerbose", () => {
  test("strips -v and --verbose before --", () => {
    expect(takeVerbose(["-v", "list"], {})).toEqual({ argv: ["list"], verbose: true })
    expect(takeVerbose(["list", "--verbose"], {})).toEqual({ argv: ["list"], verbose: true })
    expect(takeVerbose(["list"], {})).toEqual({ argv: ["list"], verbose: false })
  })

  test("leaves -v after -- for ssh", () => {
    expect(takeVerbose(["connect", "box", "--", "-v"], {})).toEqual({
      argv: ["connect", "box", "--", "-v"],
      verbose: false,
    })
  })

  test("XYNE_VERBOSE=1 is enough", () => {
    expect(takeVerbose(["list"], { XYNE_VERBOSE: "1" }).verbose).toBe(true)
    expect(isVerbose({ XYNE_VERBOSE: "1" })).toBe(true)
    expect(isVerbose({})).toBe(false)
  })
})

import { describe, expect, test } from "bun:test"
import { shellQuote, shellQuoteAll } from "./quote.ts"

describe("shellQuote", () => {
  test("leaves safe tokens alone", () => {
    expect(shellQuote("/home/u/.pu-state/ssh-proxy")).toBe("/home/u/.pu-state/ssh-proxy")
    expect(shellQuote("mybox")).toBe("mybox")
  })

  test("quotes empty and spaces", () => {
    expect(shellQuote("")).toBe("''")
    expect(shellQuote("hello world")).toBe("'hello world'")
  })

  test("escapes single quotes", () => {
    expect(shellQuote("it's")).toBe(`'it'\\''s'`)
  })

  test("joins argv", () => {
    expect(shellQuoteAll(["ssh", "-T", "pu@pu"])).toBe("ssh -T pu@pu")
  })
})
